#include <stdio.h>
#include <stdlib.h>

long long countBelow(const long long* arr, size_t len, long long threshold) {
    long long count = 0;
    for (size_t i = 0; i < len; i++) {
        if (arr[i] < threshold) {
            count++;
        }
    }
    return count;
}

int main(void) {
    // Test 1: normal case
    long long arr1[] = {1, 2, 3, 4, 5};
    printf("%lld\n", countBelow(arr1, 5, 4));

    // Test 2: empty array
    long long* arr2 = NULL;
    printf("%lld\n", countBelow(arr2, 0, 10));

    // Test 3: all elements below threshold
    long long arr3[] = {-5, -10, -15};
    printf("%lld\n", countBelow(arr3, 3, 0));

    // Test 4: no elements below threshold
    long long arr4[] = {100, 200, 300};
    printf("%lld\n", countBelow(arr4, 3, 50));

    // Test 5: mixed with zero and negative threshold
    long long arr5[] = {0, -5, 5, -10, 10};
    printf("%lld\n", countBelow(arr5, 5, 0));

    return 0;
}

