import java.util.Arrays;

public class Solution {
    public static long countBelow(long[] arr, long threshold) {
        long count = 0L;
        for (int i = 0; i < arr.length; i++) {
            if (arr[i] < threshold) {
                count++;
            }
        }
        return count;
    }

    public static void main(String[] args) {
        long[][] testArrays = {
            {},
            {5},
            {1, 2, 3, 4, 5},
            {-10, -5, 0, 5, 10},
            {Long.MIN_VALUE, 0, Long.MAX_VALUE}
        };
        long[] thresholds = {3, 5, 3, 0, 0};
        String[] descriptions = {
            "Empty array",
            "Single element below threshold",
            "Mixed elements with threshold 3",
            "Negative and positive with threshold 0",
            "Extreme values with threshold 0"
        };

        for (int i = 0; i < testArrays.length; i++) {
            long result = countBelow(testArrays[i], thresholds[i]);
            System.out.println(result);
        }
    }
}
